/**
 * 全日本雪場索引
 *
 * 名單來源：日文維基百科「日本のスキー場一覧」（CC BY-SA 4.0），2026-09-15 取得，
 * 2026-11-16 重新比對過一次 —— 維基當時新增的項目都是已廃止或已合併的雪場，所以名單沒有變動。
 * 只收錄現存雪場（排除各段「廃止・休止中」與註記為廃止／休止／合併的條目）。
 *
 * 數字（標高、雪道數、纜車數、最大傾斜、最長滑走距離）與座標：
 * 取自各雪場的日文維基百科條目的 {{スキー場}} 資訊框，2026-11-16 以 MediaWiki API 取得。
 *
 * ⚠️ 這些數字是「次級來源」，跟上面 10 張完整卡片不同等級：
 * 卡片上的每個數字都回雪場官網查證過並標了查證日期，索引這裡沒有。
 * 維基的資訊框不一定標出處，也可能過期，所以頁面上一律寫明來源是維基百科、
 * 並附上條目連結讓使用者自己核對。用途是「快速比較規模」，不是行程決策依據。
 *
 * 資料自我檢查（寧可留白，不要登錯的數字）：
 *   - 最高地點不高於最低地點 → 三個高度數字都不登（1 筆）
 *   - 標高差與（最高−最低）相差超過 60 公尺 → 標高差不登（3 筆）
 *
 * officialUrl 原本取自各條目對應 Wikidata 項目的「公式ウェブサイト」(P856)，
 * 2026-11-16 再從資訊框的「公式HP」補上 79 筆，仍查不到的為 null。
 *
 * 這個檔案是用腳本產生的，不要手動逐行改 —— 要更新請重跑產生流程。
 */
export interface DirectoryResort {
  id: string;
  name: string;
  prefecture: string;
  region: string;
  gateway: 'tokyo' | 'hokkaido' | 'other';
  officialUrl: string | null;
  /** 日文維基百科條目名稱；沒有條目的小雪場為 undefined */
  wiki?: string;
  lat?: number;
  lon?: number;
  /** 最高地點（公尺） */
  top?: number;
  /** 最低地點（公尺） */
  base?: number;
  /** 標高差（公尺） */
  vertical?: number;
  /** 雪道數 */
  courses?: number;
  /** 索道（纜車、吊椅）數 */
  lifts?: number;
  /** 最大傾斜（度） */
  maxGradient?: number;
  /** 最長滑走距離（公尺） */
  longestRun?: number;
}

